<script setup>
import DateInput from '../components/DateInput.vue';
import CfopInput from '../components/CfopInput.vue';
import {ref,computed,watch} from 'vue';import Icon from '../components/Icon.vue';import EmptyState from '../components/EmptyState.vue';
import {state,company,api,scope,useResource,rows,notify,changed,ask} from '../lib/workspace';
import {can,allowedApi,writable} from '../lib/workspace';
import {navigate} from '../lib/workspace';import {money,date,dateTime,cents} from '../lib/format';
const routine=computed(()=>state.module==='financial'?'financial.reconciliation':'fiscal.imports');
const selected=ref([]),postingMode=ref('book'),postingPreview=ref(null),cfopOverrides=ref({});let postingSequence=0;
watch(()=>[state.module,can('fiscal.documents','book')],()=>{postingMode.value=can('fiscal.documents','book')?'book':'pending'},{immediate:true});
const directPosting=computed(()=>state.module==='fiscal'&&postingMode.value==='book'&&can('fiscal.documents','book'));
const documentRows=computed(()=>directPosting.value&&postingPreview.value?postingPreview.value.documents:preview.value?.documents||[]);
const mappingRequirements=computed(()=>{const found=new Map();for(const d of preview.value?.documents||[]){const rows=d.items?.length?d.items:d.analytics?.length?d.analytics:[d];for(const i of rows){if(i.cfop||d.cfop)continue;const source=i.source_cfop||(d.source_cfops||[])[0]||'';if(!source)continue;const key=`${d.direction}:${d.model}:${source}`;found.set(key,{key,source,direction:d.direction,model:d.model,date:d.posting_date});}}return [...found.values()]});
watch(cfopOverrides,()=>{postingSequence++;postingPreview.value=null},{deep:true});
watch(postingMode,()=>{postingSequence++;postingPreview.value=null;if(preview.value&&preview.value.status!=='confirmed'&&directPosting.value)preparePosting()});
async function preparePosting(){if(!preview.value||preview.value.status==='confirmed'||!directPosting.value)return;const n=++postingSequence,ctx=previewContext.value,batch=preview.value;busy.value=true;error.value='';try{const mappings=Object.fromEntries(Object.entries(cfopOverrides.value).filter(([,v])=>v));const r=await api(scope(`/imports/${batch.id}/posting-preview`,ctx.id),{method:'POST',body:{cfop_mappings:mappings}});if(n!==postingSequence||ctx.id!==state.companyId||ctx.module!==state.module)return;postingPreview.value=r;selected.value=r.documents.filter(d=>d._eligibility?.status==='eligible'&&d.import_posting?.eligible).map(d=>d._selection);selected.value.push(...(r.transactions||[]).filter(t=>t._eligibility?.status==='eligible').map(t=>t._selection));}catch(e){if(n===postingSequence)error.value=e.message;}finally{busy.value=false}}

const postingInput=ref(null),input=ref(null),file=ref(null),preview=ref(null),busy=ref(false),error=ref(''),result=ref(null),bankAccount=ref(''),options=ref({date_format:'',encoding:'auto',delimiter:';',decimal_separator:'',thousands_separator:'auto',posting_date:''}),previewContext=ref(null),showOptions=ref(false),dragging=ref(false);
const {data:history,reload}=useResource(async()=>state.companyId?rows(await api(scope('/imports'))).filter(h=>h.period.slice(0,4)===state.period.slice(0,4)&&(state.module==='financial'?h.transactions_count:h.documents_count)):[]);
let sequence=0;
const blocking=computed(()=>preview.value?.issues?.filter(i=>['error','fatal'].includes(i.severity))||[]);
watch(()=>[state.companyId,state.period.slice(0,4),state.module],()=>{sequence++;postingSequence++;postingPreview.value=null;cfopOverrides.value={};busy.value=false;file.value=null;preview.value=null;previewContext.value=null;result.value=null;error.value='';bankAccount.value='';});
function choose(f){if(!f||busy.value)return;sequence++;if(f.size>20*1024*1024){error.value='O arquivo deve ter até 20 MB.';return;}file.value=f;postingSequence++;postingPreview.value=null;cfopOverrides.value={};preview.value=null;result.value=null;error.value='';}
const encode=f=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f);});
function readingOptions(){const o={...options.value};if(!o.posting_date)delete o.posting_date;if(!o.date_format)delete o.date_format;if(!o.decimal_separator)delete o.decimal_separator;if(o.thousands_separator==='auto')delete o.thousands_separator;return o;}
async function analyze(){
  if(!file.value||busy.value)return;
  if(postingInput.value&&!postingInput.value.reportValidity()){error.value='Confira a data de escrituração no formato DD/MM/AAAA.';return;}
  const seq=++sequence,selectedFile=file.value,ctx={id:state.companyId,period:state.period,module:state.module,name:company.value?.trade_name||company.value?.name};
  const settings=readingOptions(),bank=bankAccount.value;busy.value=true;error.value='';
  try{
    const content=await encode(selectedFile);
    if(seq!==sequence)return;
    const data=await api(scope('/imports/preview',ctx.id),{method:'POST',body:{filename:selectedFile.name,content_base64:content,period:ctx.period,options:settings,bank_account:bank}});
    if(seq!==sequence||ctx.id!==state.companyId||(ctx.period.slice(0,4)!==state.period.slice(0,4)||ctx.module!==state.module))return;
    preview.value=data;selected.value=[...(data.documents||[]),...(data.transactions||[])].filter(r=>r._eligibility?.status==='eligible').map(r=>r._selection);previewContext.value=ctx;await reload();if(directPosting.value)await preparePosting();
  }catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)busy.value=false;}
}
async function confirm(){
  if(!preview.value||blocking.value.length||busy.value)return;
  if(preview.value.transactions?.length&&!bankAccount.value.trim()){error.value='Identifique a conta bancária para importar o extrato.';return;}
  const batch=preview.value,ctx={...previewContext.value},seq=sequence,bank=bankAccount.value;
  if(directPosting.value&&!postingPreview.value){error.value='Prepare a escrituração depois de conferir os CFOPs.';return;}
  const posting=directPosting.value?{posting_mode:'book',posting_hash:postingPreview.value.posting_hash,cfop_mappings:Object.fromEntries(Object.entries(cfopOverrides.value).filter(([,v])=>v))}:{posting_mode:'pending'};
  if(!await ask({title:'Confirmar importação?',message:`Os registros serão vinculados a ${ctx.name}, no exercício ${ctx.period.slice(0,4)}, somente nos registros selecionados. ${directPosting.value?'Os documentos selecionados já ficarão escriturados no Fiscal, sem criar partidas ou títulos. Poderão ser editados conforme os bloqueios e vínculos.':'Documentos fiscais ficarão pendentes de conferência.'}`,confirmLabel:'Importar registros'}))return;
  if(seq!==sequence||ctx.id!==state.companyId||(ctx.period.slice(0,4)!==state.period.slice(0,4)||ctx.module!==state.module)){error.value='O contexto mudou. Abra a prévia na empresa e competência corretas.';return;}
  busy.value=true;error.value='';
  try{
    const response=await api(scope(`/imports/${batch.id}/confirm`,ctx.id),{method:'POST',body:{preview_hash:batch.preview_hash,bank_account:bank,selected:selected.value,...posting}});
    if(seq!==sequence)return;
    result.value=response;batch.status='confirmed';changed();notify(directPosting.value?`${response.documents_booked} documento(s) escriturado(s). A origem permanece preservada.`:'Importação confirmada. Registros disponíveis para conferência.');
  }catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)busy.value=false;}
}
async function inspect(h){
  if(busy.value)return;
  const seq=++sequence,ctx={id:state.companyId,period:state.period,module:state.module,name:company.value?.trade_name||company.value?.name};error.value='';busy.value=true;
  try{
    const inspected=await api(scope(`/imports/${h.id}`,ctx.id));
    if(seq!==sequence||ctx.id!==state.companyId||(ctx.period.slice(0,4)!==state.period.slice(0,4)||ctx.module!==state.module))return;
    postingSequence++;postingPreview.value=null;cfopOverrides.value={};preview.value=inspected;selected.value=[...(inspected.documents||[]),...(inspected.transactions||[])].filter(r=>r._eligibility?.status==='eligible').map(r=>r._selection);previewContext.value={...ctx,period:inspected.period};bankAccount.value=inspected.bank_account||inspected.bank_account_hint||'';result.value=inspected.confirmation||null;file.value=null;if(inspected.status!=='confirmed'&&directPosting.value)await preparePosting();
  }catch(e){if(seq===sequence)error.value=e.message;}finally{if(seq===sequence)busy.value=false;}
}
function totalCents(d){if(d.total_cents!==undefined)return d.total_cents;return cents(d.total||'0.00')||0;}
</script>
<template><div class="view"><header class="view-heading"><div><div class="eyebrow">ENTRADA DE DADOS</div><h1>{{state.module==='financial'?'Importação de extratos':'Importações fiscais'}}</h1><p>Preserve os arquivos de origem e confira os registros antes de confirmar.</p></div><span class="badge neutral"><Icon name="shield" :size="14"/>Importação com prévia e histórico</span></header>
<div class="import-layout"><section class="panel upload-panel"><div class="panel-heading"><div><h2>Selecionar arquivo</h2><p>Empresa: {{company?.trade_name||company?.name}}</p></div><Icon name="import"/></div><div class="dropzone" :class="{dragging}" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="dragging=false;choose($event.dataTransfer.files[0])"><span class="upload-circle"><Icon :name="file?'filecheck':'import'" :size="28"/></span><strong>{{file?.name||'Arraste o arquivo para esta área'}}</strong><span>{{file?`${(file.size/1024).toFixed(1)} KB · pronto para analisar`:'ou selecione no seu computador'}}</span><input ref="input" type="file" accept=".xml,.txt,.sped,.efd,.zip,.7z,.rar,.csv,.ofx,.qfx,.qif,.ofc" @change="choose($event.target.files[0])" aria-label="Selecionar arquivo de importação"/><button class="button outline" type="button" @click="input.click()" :disabled="busy">Selecionar arquivo</button><small>XML · SPED/TXT · ZIP / 7z / RAR · CSV · OFX · QIF · OFC<br>Limite de 20 MB por arquivo. Leiautes não reconhecidos geram pendência.</small></div><div class="upload-options"><button class="text-button" @click="showOptions=!showOptions"><Icon name="settings" :size="16"/>Opções de leitura e escrituração<Icon name="down" :size="15"/></button><div v-show="showOptions" class="form-grid three"><label>Formato da data<select v-model="options.date_format"><option value="">Padrão do formato</option><option value="DMY">Dia / mês / ano</option><option value="YMD">Ano / mês / dia</option><option value="MDY">Mês / dia / ano</option></select></label><label>Codificação<select v-model="options.encoding"><option value="auto">Detectar com conferência</option><option value="utf-8">UTF-8</option><option value="cp1252">Windows-1252</option></select></label><label>Separador<select v-model="options.delimiter"><option value=";">Ponto e vírgula</option><option value=",">Vírgula</option><option :value="'\t'">Tabulação</option></select></label><label>Separador decimal<select v-model="options.decimal_separator"><option value="">Padrão do formato</option><option value=",">Vírgula (1.234,56)</option><option value=".">Ponto (1,234.56)</option></select></label><label>Separador de milhares<select v-model="options.thousands_separator"><option value="auto">Padrão do formato</option><option value=".">Ponto</option><option value=",">Vírgula</option><option value="">Sem separador</option></select></label><label>Data de escrituração do XML<DateInput ref="postingInput" v-model="options.posting_date"/><small>Vazio: emissão proposta para conferência.</small></label><p class="field-help span-3">Layout bancário: cabeçalhos data, valor, historico e documento. Valores negativos representam saídas; positivos, entradas. Datas e valores ambíguos exigem configuração. Separe extratos com convenções numéricas diferentes em lotes distintos.</p></div><label>Conta bancária do extrato <small>Somente para importações financeiras.</small><input v-model="bankAccount" placeholder="Ex.: Banco / agência / conta"/></label></div><div v-if="error" class="message error" role="alert">{{error}}</div><div class="panel-action"><button class="button primary full" v-allow="[routine,'import']" @click="analyze" :disabled="!file||busy"><Icon :name="busy?'loading':'search'"/>{{busy?'Processando arquivo...':'Analisar e gerar prévia'}}</button></div></section>
<section class="panel import-history"><div class="panel-heading"><div><h2>Histórico de arquivos</h2><p>Processamentos desta empresa.</p></div><span class="badge neutral">{{history.length}}</span></div><div v-if="history.length" class="history-list"><button v-for="h in history.slice().reverse()" :key="h.id" @click="inspect(h)"><span class="file-icon"><Icon name="file"/></span><span><strong>{{h.filename}}</strong><small>{{dateTime(h.created_at)}} · {{h.format||'Arquivo'}}</small></span><span class="badge" :class="h.status==='confirmed'?'success':'neutral'">{{h.status==='confirmed'?'Importado':'Prévia'}}</span></button></div><EmptyState v-else title="Nenhum arquivo processado" text="O histórico preservará origem, resultado e identificação de cada importação." icon="folder"/></section></div>
<section v-if="preview" class="panel preview-panel"><div class="panel-heading"><div><h2>Prévia · {{preview.filename}}</h2><p>{{previewContext?.name}} · {{preview.period.split('-').reverse().join('/')}} · {{preview.format}}</p></div><a v-allow="[routine,'export']" class="button outline small" :href="`/api${scope(`/imports/${preview.id}/original`,previewContext.id)}`" download>Baixar original</a><span class="badge" :class="blocking.length?'warning':preview.status==='confirmed'?'success':'info'">{{blocking.length?'Requer correção':preview.status==='confirmed'?'Importação confirmada':'Aguardando confirmação'}}</span></div><div class="summary-strip"><div><strong>{{preview.documents?.length||0}}</strong><span>documentos</span></div><div><strong>{{preview.transactions?.length||0}}</strong><span>movimentos bancários</span></div><div><strong>{{preview.issues?.length||0}}</strong><span>ocorrências</span></div><span class="push-right mono subtle">Origem SHA-256 {{preview.sha256?.slice(0,12)}}…</span></div><div v-if="preview.issues?.length" class="issues-list"><div v-for="(issue,i) in preview.issues" :key="i" class="message" :class="['error','fatal'].includes(issue.severity)?'error':'warning'"><Icon name="alert" :size="17"/><div><strong>{{issue.code}}</strong><span>{{issue.message}}</span></div></div></div>
<section v-if="state.module==='fiscal'&&preview.documents?.length&&preview.status!=='confirmed'" class="panel-body"><div class="form-grid"><label>Ao confirmar esta importação<select v-model="postingMode" aria-label="Modo de escrituração da importação"><option v-if="can('fiscal.documents','book')" value="book">Importar e escriturar no Fiscal</option><option value="pending">Importar para conferência individual</option></select></label><div v-if="directPosting" class="actions"><button class="button outline" :disabled="busy" @click="preparePosting">Preparar escrituração</button><button v-if="can('fiscal.masters')" class="text-button" @click="navigate('cfop')">CFOP e associações da empresa</button></div></div><template v-if="directPosting"><div v-if="mappingRequirements.length" class="form-grid three"><label v-for="r in mappingRequirements" :key="r.key">{{r.direction==='incoming'?'Entrada':'Saída'}} · modelo {{r.model}} · origem {{r.source}}<CfopInput v-model="cfopOverrides[r.key]" :direction="r.direction" :date="r.date" placeholder="Usar associação da empresa" :aria-label="`CFOP de escrituração para ${r.key}`"/></label></div><p>As escolhas deste lote não alteram as associações salvas da empresa. O CFOP e os valores originais são preservados; não há cálculo de tributos, criação de títulos ou contabilização implícita.</p><p v-if="!postingPreview" class="message info">Prepare a escrituração para validar os CFOPs e liberar a seleção.</p></template></section><div v-if="preview.documents?.length" class="table-scroll preview-table"><table><thead><tr><th>Selecionar</th><th>Competência / diagnóstico</th><th>Documento</th><th>Participante</th><th>Emissão</th><th>Operação</th><th class="right">Total</th></tr></thead><tbody><tr v-for="(d,i) in documentRows" :key="i"><td><input type="checkbox" v-model="selected" :value="d._selection" :disabled="d._eligibility?.status!=='eligible'||preview.status==='confirmed'||(directPosting&&(!postingPreview||!d.import_posting?.eligible))" :aria-label="`Selecionar documento ${d.number}`"/></td><td>{{d._eligibility?.period}} · {{directPosting?(d.import_posting?.reason||'Prepare a escrituração'):d._eligibility?.reason}}<small v-if="directPosting&&d.import_posting?.eligible" class="cell-secondary">CFOP {{d.items?.length?[...new Set(d.items.map(i=>i.cfop))].join(', '):d.cfop}}</small></td><td class="mono">{{d.number}}</td><td>{{d.partner_name}}</td><td>{{date(d.issue_date)}}</td><td>{{d.direction==='incoming'?'Entrada':d.direction==='outgoing'?'Saída':'A conferir'}}</td><td class="right money">{{money(totalCents(d))}}</td></tr></tbody></table></div><div v-if="preview.transactions?.length" class="table-scroll preview-table"><table><thead><tr><th>Selecionar</th><th>Diagnóstico</th><th>Data</th><th>Histórico</th><th>Referência</th><th class="right">Valor</th></tr></thead><tbody><tr v-for="(t,i) in preview.transactions" :key="i"><td><input type="checkbox" v-model="selected" :value="t._selection" :disabled="t._eligibility?.status!=='eligible'||preview.status==='confirmed'" aria-label="Selecionar movimento"/></td><td>{{t._eligibility?.reason}}</td><td>{{date(t.date)}}</td><td>{{t.description}}</td><td class="mono">{{t.reference||t.external_id}}</td><td class="right money" :class="Number(t.amount)<0?'negative':'positive'">{{money(t.amount_cents??Math.round(Number(t.amount)*100))}}</td></tr></tbody></table></div><div v-if="result" class="message success"><Icon name="checks"/><span>{{result.documents_booked||0}} documentos escriturados · {{result.documents_created||0}} documentos e {{result.transactions_created||0}} movimentos incluídos. {{(result.documents_duplicate||0)+(result.transactions_duplicate||0)}} registros já existentes preservados sem duplicação.</span></div><footer class="panel-action split"><span class="field-help">Confirmar a importação não aprova regras fiscais nem efetua baixas financeiras.</span><button v-if="preview.status!=='confirmed'" class="button primary" v-allow="[routine,'import']" @click="confirm" aria-label="Confirmar importação" :disabled="busy||blocking.length>0||!selected.length||(directPosting&&!postingPreview)"><Icon :name="busy?'loading':'check'"/>Confirmar {{selected.length}} selecionados</button><button v-else class="button outline" @click="navigate(preview.transactions?.length?'reconcile':'documents')">{{preview.transactions?.length?'Abrir conciliação':'Abrir escrituração'}}<Icon name="arrow"/></button></footer></section>
</div></template>
